const { spawn } = require('child_process');
const http = require('http');
const path = require('path');
const fs = require('fs');

async function main() {
  const appHtmlPath = path.resolve(__dirname, '../app/index.html');
  const appFileUrl = `file://${appHtmlPath}`;
  const cdpPort = 9348;
  const userDataDir = `/tmp/chrome-diag-${Date.now()}`;

  const chrome = spawn('google-chrome-stable', [
    '--headless=new',
    `--remote-debugging-port=${cdpPort}`,
    `--user-data-dir=${userDataDir}`,
    '--no-sandbox',
    '--disable-gpu',
    '--window-size=1920,1080',
    appFileUrl
  ]);

  const cleanup = () => {
    try { chrome.kill('SIGKILL'); } catch (e) {}
    try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch (e) {}
  };
  process.on('exit', cleanup);

  let listRes = null;
  for (let attempt = 0; attempt < 25; attempt++) {
    await new Promise(r => setTimeout(r, 200));
    try {
      listRes = await new Promise((resolve, reject) => {
        http.get(`http://127.0.0.1:${cdpPort}/json/list`, (res) => {
          let data = '';
          res.on('data', chunk => data += chunk);
          res.on('end', () => {
            try { resolve(JSON.parse(data)); } catch (e) { reject(e); }
          });
        }).on('error', reject);
      });
      if (listRes && listRes.length > 0) break;
    } catch (e) {}
  }

  if (!listRes) throw new Error('Headless Chromium CDP connection failed');
  const pageTarget = listRes.find(t => t.url.includes('cinejoy-webos')) || listRes[0];
  const ws = new WebSocket(pageTarget.webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);

  let msgId = 1;
  function evaluate(code) {
    return new Promise((resolve, reject) => {
      const id = msgId++;
      const handler = (event) => {
        try {
          const data = JSON.parse(event.data);
          if (data.id === id) {
            ws.removeEventListener('message', handler);
            if (data.error) reject(new Error(data.error.message));
            else resolve(data.result.result.value);
          }
        } catch (err) { reject(err); }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id, method: 'Runtime.evaluate', params: { expression: code, returnByValue: true, awaitPromise: true } }));
    });
  }

  await new Promise(r => setTimeout(r, 600));

  console.log('--- Initial State ---');
  let s = await evaluate(`(() => {
    const h = document.getElementById('app-header');
    const b = document.getElementById('bgBlur');
    return {
      hExists: Boolean(h),
      hTag: h ? h.tagName : null,
      hId: h ? h.id : null,
      hClass: h ? h.className : null,
      hOpacity: h ? window.getComputedStyle(h).opacity : null,
      hTransition: h ? window.getComputedStyle(h).transition : null,
      bOpacity: b ? window.getComputedStyle(b).opacity : null,
      bTransition: b ? window.getComputedStyle(b).transition : null
    };
  })()`);
  console.log('Initial:', s);

  console.log('--- Adding body.scrolled ---');
  await evaluate(`document.body.classList.add('scrolled')`);
  for (let t of [100, 300, 500, 700]) {
    await new Promise(r => setTimeout(r, t === 100 ? 100 : 200));
    let cur = await evaluate(`(() => {
      const h = document.getElementById('app-header');
      const b = document.getElementById('bgBlur');
      return {
        time: ${t},
        hOpacity: window.getComputedStyle(h).opacity,
        bOpacity: window.getComputedStyle(b).opacity
      };
    })()`);
    console.log(`t=${t}ms:`, cur);
  }

  console.log('--- Removing body.scrolled ---');
  await evaluate(`document.body.classList.remove('scrolled')`);
  for (let t of [100, 300, 500, 700, 1000]) {
    await new Promise(r => setTimeout(r, t === 100 ? 100 : (t === 1000 ? 300 : 200)));
    let cur = await evaluate(`(() => {
      const h = document.getElementById('app-header');
      const b = document.getElementById('bgBlur');
      return {
        time: ${t},
        hOpacity: window.getComputedStyle(h).opacity,
        bOpacity: window.getComputedStyle(b).opacity
      };
    })()`);
    console.log(`t=${t}ms restore:`, cur);
  }

  console.log('--- Adding #app.scrolled ---');
  await evaluate(`document.getElementById('app').classList.add('scrolled')`);
  for (let t of [100, 300, 500, 700]) {
    await new Promise(r => setTimeout(r, t === 100 ? 100 : 200));
    let cur = await evaluate(`(() => {
      const h = document.getElementById('app-header');
      const b = document.getElementById('bgBlur');
      const appEl = document.getElementById('app');
      return {
        time: ${t},
        appClass: appEl.className,
        bodyClass: document.body.className,
        hOpacity: window.getComputedStyle(h).opacity,
        bOpacity: window.getComputedStyle(b).opacity
      };
    })()`);
    console.log(`t=${t}ms app.scrolled:`, cur);
  }

  cleanup();
  process.exit(0);
}

main().catch(err => {
  console.error(err);
